package com.hms.reporting;
import com.hms.model.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.*;
import org.junit.jupiter.api.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AnalyticsServiceTest {
 EntityManager em;AnalyticsService service;Map<Class<?>,List<?>> stored;
 @BeforeEach @SuppressWarnings({"unchecked","rawtypes"}) void setup(){em=mock(EntityManager.class);stored=new HashMap<>();when(em.createQuery(anyString(),any(Class.class))).thenAnswer(inv->{Class<?> type=inv.getArgument(1);TypedQuery query=mock(TypedQuery.class);when(query.getResultList()).thenAnswer(q->stored.getOrDefault(type,List.of()));return query;});service=new AnalyticsService(em,new ObjectMapper());}
 Authentication role(String r){return new UsernamePasswordAuthenticationToken("test",null,List.of(new SimpleGrantedAuthority("ROLE_"+r)));}
 AnalyticsService.Filter filter(String from,String to){return new AnalyticsService.Filter(from==null?null:LocalDate.parse(from),to==null?null:LocalDate.parse(to),"day",null,null,null,null,null,null);}
 <T extends BaseRecord>T row(Class<T> type,long id,String details,String status){try{T r=type.getDeclaredConstructor().newInstance();r.id=id;r.name="Record "+id;r.details=details;r.status=status;r.createdAt=Instant.parse("2026-10-01T00:00:00Z");return r;}catch(Exception e){throw new RuntimeException(e);}}
 Object metric(AnalyticsService.Report r,String label){return r.metrics().stream().filter(m->m.label().equals(label)).findFirst().orElseThrow().value();}
 @Test void reportRoleMatrixRejectsBeforeReadingData(){Map<String,List<String>> expected=Map.of("ADMIN",List.of("patients","appointments","revenue","pharmacy","laboratory","staff"),"DOCTOR",List.of("patients","appointments","laboratory"),"NURSE",List.of("patients"),"RECEPTIONIST",List.of("patients","appointments"),"LAB",List.of("laboratory"),"PHARMACIST",List.of("pharmacy"),"ACCOUNTANT",List.of("revenue"),"PATIENT",List.of());for(var entry:expected.entrySet()){assertEquals(entry.getValue(),service.categories(role(entry.getKey())));for(String category:AnalyticsService.ACCESS.keySet()){if(!entry.getValue().contains(category))assertEquals(403,assertThrows(ResponseStatusException.class,()->service.generate(category,filter(null,null),role(entry.getKey()))).getStatusCode().value());}}verify(em,never()).createQuery(anyString(),any(Class.class));}
 @Test void revenueUsesPaymentsAndAllocatesPartialPayments(){stored.put(Bill.class,List.of(row(Bill.class,1,"{\"patientId\":5,\"total\":1000,\"consultationCharge\":400,\"laboratoryCharge\":200,\"pharmacyCharge\":300,\"admissionCharge\":100,\"billDate\":\"2026-10-01\"}","PAID")));stored.put(Payment.class,List.of(row(Payment.class,1,"{\"billId\":1,\"amount\":500,\"paymentDate\":\"2026-10-02\"}","COMPLETED"),row(Payment.class,2,"{\"billId\":1,\"amount\":500,\"paymentDate\":\"2026-11-01\"}","COMPLETED"),row(Payment.class,3,"{\"billId\":1,\"amount\":500,\"paymentDate\":\"2026-10-02\"}","PENDING")));var report=service.generate("revenue",filter("2026-10-01","2026-10-31"),role("ADMIN"));assertEquals(new BigDecimal("500.00"),metric(report,"Collected revenue"));assertEquals(new BigDecimal("500.00"),metric(report,"Outstanding on selected bills"));assertEquals(new BigDecimal("200.00"),metric(report,"Consultation revenue"));assertEquals(new BigDecimal("100.00"),metric(report,"Laboratory revenue"));assertEquals(0L,metric(report,"Fully paid bills"));}
 @Test void revenueKeepsUnlinkedPaymentsUnattributedAndPrePeriodSettlements(){stored.put(Bill.class,List.of(row(Bill.class,1,"{\"total\":100,\"billDate\":\"2026-10-01\"}","UNPAID")));stored.put(Payment.class,List.of(row(Payment.class,1,"{\"billId\":1,\"amount\":40,\"paymentDate\":\"2026-09-30\"}","ACTIVE"),row(Payment.class,2,"{\"billId\":99,\"amount\":25,\"paymentDate\":\"2026-10-02\"}","ACTIVE")));var report=service.generate("revenue",filter("2026-10-01","2026-10-31"),role("ACCOUNTANT"));assertEquals(new BigDecimal("25.00"),metric(report,"Collected revenue"));assertEquals(new BigDecimal("60.00"),metric(report,"Outstanding on selected bills"));assertEquals(new BigDecimal("25.00"),report.charts().get(1).series().stream().filter(p->p.get("label").equals("Unattributed")).findFirst().orElseThrow().get("value"));}
 @Test void appointmentFiltersJoinDoctorDepartmentAndIncludeEndDate(){stored.put(Doctor.class,List.of(row(Doctor.class,7,"{\"departmentId\":3}","ACTIVE")));stored.put(Appointment.class,List.of(row(Appointment.class,1,"{\"date\":\"2026-10-31\",\"doctorId\":7,\"patientId\":2}","CANCELLED"),row(Appointment.class,2,"{\"date\":\"2026-11-01\",\"doctorId\":7,\"patientId\":2}","SCHEDULED"),row(Appointment.class,3,"{\"date\":\"2026-10-31\",\"doctorId\":8,\"patientId\":2}","COMPLETED"),row(Appointment.class,4,"{\"date\":\"2026-10-31\",\"doctorId\":7,\"patientId\":2}","ARCHIVED")));var f=new AnalyticsService.Filter(LocalDate.parse("2026-10-01"),LocalDate.parse("2026-10-31"),"month",2L,7L,3L,null,null,null);var report=service.generate("appointments",f,role("DOCTOR"));assertEquals(1,metric(report,"Appointments"));assertEquals(new BigDecimal("100.00"),metric(report,"Cancellation rate"));assertEquals("2026-10-01",report.charts().get(0).series().get(0).get("label"));}
 @Test void laboratoryTurnaroundUsesExplicitTimestampsAndOmitsResults(){stored.put(LaboratoryTest.class,List.of(row(LaboratoryTest.class,1,"{\"requestedAt\":\"2026-10-01T09:00\",\"completedAt\":\"2026-10-01T11:30\",\"testName\":\"Blood\",\"result\":\"secret clinical result\"}","COMPLETED"),row(LaboratoryTest.class,2,"{\"testName\":\"Urine\"}","PROCESSING")));var report=service.generate("laboratory",filter("2026-10-01","2026-10-31"),role("LAB"));assertEquals(new BigDecimal("2.50"),metric(report,"Average turnaround"));assertEquals(1,metric(report,"Tests with turnaround timestamps"));assertEquals(1L,metric(report,"Awaiting results"));assertFalse(report.tables().toString().contains("secret clinical result"));}
 @Test void patientReportCountsOverlappingStaysAndDoesNotExposeClinicalData(){stored.put(Patient.class,List.of(row(Patient.class,1,"{\"gender\":\"Female\",\"dateOfBirth\":\"2000-01-01\",\"phone\":\"private phone\"}","ACTIVE")));stored.put(Admission.class,List.of(row(Admission.class,2,"{\"patientId\":1,\"admissionDate\":\"2026-09-25\",\"dischargeDate\":\"2026-10-03\"}","DISCHARGED")));stored.put(MedicalRecord.class,List.of(row(MedicalRecord.class,3,"{\"patientId\":1,\"visitDate\":\"2026-10-04\",\"visitType\":\"OUTPATIENT\",\"diagnosis\":\"private diagnosis\"}","ACTIVE")));var report=service.generate("patients",filter("2026-10-01","2026-10-31"),role("NURSE"));assertEquals(1L,metric(report,"Inpatients in period"));assertEquals(1L,metric(report,"Discharges in period"));assertEquals(1L,metric(report,"Outpatients with recorded visits"));assertFalse(report.tables().toString().contains("private"));}
 @Test void pharmacyDistinguishesInventorySnapshotFromPeriodMovements(){String expired=LocalDate.now(AnalyticsService.ZONE).minusDays(1).toString();stored.put(PharmacyItem.class,List.of(row(PharmacyItem.class,1,"{\"quantity\":3,\"reorderLevel\":5,\"expiryDate\":\""+expired+"\"}","ACTIVE")));PharmacyMovement movement=new PharmacyMovement();movement.id=1L;movement.medicineId=1L;movement.type="DISPENSE";movement.quantity=new BigDecimal("2");movement.unitPrice=new BigDecimal("20");movement.occurredAt=Instant.parse("2026-10-15T08:00:00Z");stored.put(PharmacyMovement.class,List.of(movement));var report=service.generate("pharmacy",filter("2026-10-01","2026-10-31"),role("PHARMACIST"));assertEquals(1L,metric(report,"Low-stock items"));assertEquals(1L,metric(report,"Expired items"));assertEquals(new BigDecimal("40.00"),metric(report,"Recorded dispensing sales"));var outside=service.generate("pharmacy",filter("2026-09-01","2026-09-30"),role("ADMIN"));assertEquals(new BigDecimal("3.00"),metric(outside,"Stock units"));assertEquals(new BigDecimal("0.00"),metric(outside,"Recorded dispensing sales"));}
 @Test void staffDoesNotAssumeMissingAttendanceMeansAbsent(){stored.put(Employee.class,List.of(row(Employee.class,1,"{\"jobTitle\":\"Nurse\"}","ACTIVE"),row(Employee.class,2,"{}","ACTIVE")));stored.put(Attendance.class,List.of(row(Attendance.class,1,"{\"employeeId\":1,\"date\":\"2026-10-02\",\"checkIn\":\"09:00\"}","ACTIVE"),row(Attendance.class,2,"{\"employeeId\":1,\"date\":\"2026-10-02\",\"checkIn\":\"09:05\"}","ACTIVE")));var report=service.generate("staff",filter("2026-10-01","2026-10-31"),role("ADMIN"));assertEquals(2,metric(report,"Employees"));assertEquals(1,metric(report,"Present employee-days"));assertEquals(0,metric(report,"Recorded absent employee-days"));}
 @Test void malformedDetailsAndMissingDatesDoNotCrashOrInventMetrics(){stored.put(Appointment.class,List.of(row(Appointment.class,1,"not json","ACTIVE"),row(Appointment.class,2,"{\"date\":\"bad-date\"}","ACTIVE")));assertEquals(0,metric(service.generate("appointments",filter(null,null),role("ADMIN")),"Appointments"));assertThrows(ResponseStatusException.class,()->new AnalyticsService.Filter(LocalDate.parse("2026-11-01"),LocalDate.parse("2026-10-01"),"day",null,null,null,null,null,null));assertThrows(ResponseStatusException.class,()->new AnalyticsService.Filter(null,null,"bad",null,null,null,null,null,null));}
}
